(() => {
  "use strict";

  const SOURCE = Object.freeze({
    repository: "https://github.com/maxcleme/beadcolors",
    license: "MIT",
    commit: "29229889daab404fb30531d4bb785fd73f7f58e3",
    revision: "beadcolors-29229889",
    retrievedAt: "2026-07-29",
  });

  const csvBase64 = {
    mard:
      "",
    hama:
      "",
    hamaMini:
      "",
    hamaMaxi:
      "",
    nabbi:
      "",
    yant:
      "",
    perler:
      "",
    perlerMini:
      "",
    perlerCaps:
      "",
    artkalA:
      "",
    artkalC:
      "",
    artkalM:
      "",
    artkalR:
      "",
    artkalS:
      "",
  };

  const manifest = [
    {
      id: "mard-221",
      brand: "MARD",
      series: "基础 221 色",
      beadSize: "2.6 / 5 mm",
      sourceKey: "mard",
      count: 221,
      include: "mard-basic",
    },
    {
      id: "mard-291",
      brand: "MARD",
      series: "完整 291 色",
      beadSize: "2.6 / 5 mm",
      sourceKey: "mard",
      count: 291,
    },
    {
      id: "hama-midi",
      brand: "Hama",
      series: "Midi",
      beadSize: "5 mm",
      sourceKey: "hama",
      count: 92,
    },
    {
      id: "hama-mini",
      brand: "Hama",
      series: "Mini",
      beadSize: "2.5 mm",
      sourceKey: "hamaMini",
      count: 78,
    },
    {
      id: "hama-maxi",
      brand: "Hama",
      series: "Maxi",
      beadSize: "10 mm",
      sourceKey: "hamaMaxi",
      count: 25,
    },
    {
      id: "nabbi",
      brand: "Nabbi",
      series: "标准色",
      beadSize: "5 mm",
      sourceKey: "nabbi",
      count: 30,
    },
    {
      id: "yant",
      brand: "Yant",
      series: "标准色",
      beadSize: "5 mm",
      sourceKey: "yant",
      count: 119,
    },
    {
      id: "perler",
      brand: "Perler",
      series: "标准色",
      beadSize: "5 mm",
      sourceKey: "perler",
      count: 103,
    },
    {
      id: "perler-mini",
      brand: "Perler",
      series: "Mini",
      beadSize: "2.6 mm",
      sourceKey: "perlerMini",
      count: 41,
    },
    {
      id: "perler-caps",
      brand: "Perler",
      series: "Caps",
      beadSize: "5 mm",
      sourceKey: "perlerCaps",
      count: 26,
    },
    {
      id: "artkal-a",
      brand: "Artkal",
      series: "A",
      beadSize: "2.6 mm",
      sourceKey: "artkalA",
      count: 145,
    },
    {
      id: "artkal-c",
      brand: "Artkal",
      series: "C",
      beadSize: "2.6 mm",
      sourceKey: "artkalC",
      count: 174,
    },
    {
      id: "artkal-m",
      brand: "Artkal",
      series: "M",
      beadSize: "2.6 mm",
      sourceKey: "artkalM",
      count: 220,
    },
    {
      id: "artkal-r",
      brand: "Artkal",
      series: "R",
      beadSize: "5 mm",
      sourceKey: "artkalR",
      count: 89,
    },
    {
      id: "artkal-s",
      brand: "Artkal",
      series: "S",
      beadSize: "5 mm",
      sourceKey: "artkalS",
      count: 199,
    },
  ];

  const cache = new Map();

  function decodeUtf8Base64(value) {
    const binary = globalThis.atob(value);
    const bytes = Uint8Array.from(binary, (character) =>
      character.charCodeAt(0),
    );
    return new TextDecoder().decode(bytes);
  }

  function parseCsv(sourceKey) {
    if (cache.has(sourceKey)) return cache.get(sourceKey);
    const encoded = csvBase64[sourceKey];
    if (!encoded) throw new Error(`Unknown BeadColors source: ${sourceKey}`);
    const colors = decodeUtf8Base64(encoded)
      .split(/\r?\n/)
      .filter(Boolean)
      .map((line, index) => {
        const fields = line.split(",");
        if (fields.length !== 6) {
          throw new Error(
            `Invalid BeadColors row ${sourceKey}:${index + 1}`,
          );
        }
        const [code, name, red, green, blue, contributor] = fields;
        return {
          code,
          name,
          r: Number(red),
          g: Number(green),
          b: Number(blue),
          contributor,
        };
      });
    cache.set(sourceKey, colors);
    return colors;
  }

  function filterColors(colors, include) {
    if (include !== "mard-basic") return colors;
    return colors.filter((color) => /^[A-HM]\d+$/.test(color.code));
  }

  function listPalettes() {
    return manifest.map((entry) => ({ ...entry, revision: SOURCE.revision }));
  }

  function getPalette(id) {
    const metadata = manifest.find((entry) => entry.id === id);
    if (!metadata) return null;
    const colors = filterColors(
      parseCsv(metadata.sourceKey),
      metadata.include,
    ).map((color) => ({ ...color }));
    return {
      ...metadata,
      revision: SOURCE.revision,
      rgbQuality: "community",
      source: SOURCE,
      colors,
    };
  }

  function validate() {
    const errors = [];
    for (const metadata of manifest) {
      const palette = getPalette(metadata.id);
      if (!palette || palette.colors.length !== metadata.count) {
        errors.push(
          `${metadata.id}: expected ${metadata.count}, received ${palette?.colors.length ?? 0}`,
        );
        continue;
      }
      const codes = new Set();
      for (const color of palette.colors) {
        if (codes.has(color.code)) {
          errors.push(`${metadata.id}: duplicate code ${color.code}`);
        }
        codes.add(color.code);
        for (const channel of ["r", "g", "b"]) {
          if (
            !Number.isInteger(color[channel]) ||
            color[channel] < 0 ||
            color[channel] > 255
          ) {
            errors.push(
              `${metadata.id}: invalid ${channel} for ${color.code}`,
            );
          }
        }
      }
    }
    return errors;
  }

  const api = Object.freeze({
    SOURCE,
    listPalettes,
    getPalette,
    validate,
  });

  if (typeof module !== "undefined" && module.exports) module.exports = api;
  globalThis.DougaoBeadPalettes = api;
})();
